private fun symbol(name: String, path: String): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 48.dp,
        defaultHeight = 48.dp,
        viewportWidth = 960f,
        viewportHeight = 960f,
    )
        .addGroup(translationY = 960f)
        .addPath(pathData = PathParser().parsePathString(path).toNodes(), fill = SolidColor(Color.Black))
        .clearGroup()
        .build()
